            {
                for (int k = 0; k < cpuScansPerFrame; k++)
                {
                    var allObjects = GameObject.FindObjectsOfType<GameObject>();
                    GC.KeepAlive(allObjects);
                }
            }

            if (stressDraw && testPrefab != null)
            {
                int n = Mathf.Max(1, cubesPerFrame);
                for (int i = 0; i < n; i++) SpawnOne();
            }
        }",
      "explicacao_didatica": "O Garbage Collector (coletor de lixo, ou GC) é um mecanismo automático da Unity e do .NET que limpa da memória objetos que não estão mais sendo utilizados. Quando strings são unidas com o operador '+' dentro de um loop de repetição ou quando novos vetores (arrays) são instanciados a cada frame, muita memória temporária é requisitada (alocação de memória na heap gerenciada). Para limpar essa montanha de dados temporários, o GC precisa congelar ou atrasar a execução do jogo para fazer a varredura, resultando no pico de tempo (gc_collect_ms) observado."
    }
